/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { MercurySystemModel } from "../../src/common/model/MercurySystemModel.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import MercuryElongationsColors from "../../src/MercuryElongationsColors.js";
import { OrbitsScreen } from "../../src/orbits/OrbitsScreen.js";
import { PlanetariumScreen } from "../../src/planetarium/PlanetariumScreen.js";
import { MercuryElongationsPreferencesModel } from "../../src/preferences/MercuryElongationsPreferencesModel.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences (wire query-parameter defaults when any are added).
  const simPreferences = new MercuryElongationsPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const system = new MercurySystemModel();

  const screens = [
    new PlanetariumScreen(system, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().planetariumStringProperty,
      tandem: Tandem.ROOT.createTandem("planetariumScreen"),
      backgroundColorProperty: MercuryElongationsColors.backgroundColorProperty,
    }),
    new OrbitsScreen(system, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().orbitsStringProperty,
      tandem: Tandem.ROOT.createTandem("orbitsScreen"),
      backgroundColorProperty: MercuryElongationsColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { MercuryElongationsColors, stringManager, simPreferences, system } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
